// ============================================================
// ВБУДОВАНІ ФОТО: щоб картинки працювали без окремої папки img.
// Це технічний блок із закодованими зображеннями, його не редагуємо.
// Нове фото для товару: впишіть шлях у його поле image вище, і воно
// замінить вбудоване (рядок звідси можна видалити).
// ============================================================
const EMBEDDED_IMAGES = {
    brazylia: 'data:image/jpeg;base64,',
    kolumbia: 'data:image/jpeg;base64,',
    etiopia: 'data:image/jpeg;base64,',
    gwatemala: 'data:image/jpeg;base64,',
    peru: 'data:image/jpeg;base64,'
};

PRODUCTS.forEach(p => {
    if (!p.image && EMBEDDED_IMAGES[p.id]) p.image = EMBEDDED_IMAGES[p.id];
});
